+	position := m.styles.render(m.styles.dim, m.positionText())
+	for _, help := range helpChoices {
+		gap := m.width - lipgloss.Width(help) - lipgloss.Width(position) - 2
+		if gap >= 1 {
+			return help + strings.Repeat(" ", gap) + position
+		}
+	}
